SELECT p.id AS product_id, p.name,p.grade,p.charge_name AS productChargeName, pi.project_status,p.brand_name,p.type,pi.id AS projectId, p.approval_status,pi.charge_name AS projectChargeName ,pi.end_time FROM product_info p INNER JOIN project_info pi ON p.id=pi.product_id WHERE P.delete_state=0
AND P.category_id=#{params.categoryId}
AND P.name LIKE concat('%',#{params.searchKeyword},'%')
AND pi.project_status IN
#{state}
AND P.id IN
#{productId}
AND pi.id NOT IN
#{productId}

SELECT p.id AS product_id, p.name,p.grade,p.charge_name AS productChargeName,
pi.project_status,p.brand_name,p.type,pi.id AS projectId,
p.approval_status,pi.charge_name AS projectChargeName ,pi.end_time FROM product_info p
INNER JOIN project_info pi ON p.id=pi.product_id
WHERE  P.delete_state=0

    AND P.category_id=#{params.categoryId}


    AND P.name LIKE concat('%',#{params.searchKeyword},'%')


    AND pi.project_status IN

        #{state}




    AND P.id IN

        #{productId}




    AND pi.id NOT IN

        #{productId}
